('ศิลปะ', 'รายวิชาพื้นฐาน', 'ม.3', 'ศ 2.1', 'ศ 2.1 ม.3/3', 'แต่งเพลงสั้นๆ จังหวะง่าย ๆ', 'ปลายทาง'),
